import http from "http";
import {FormData, Blob} from "formdata-node";

const server = http.createServer((req, res) => {
  let b = [];
  req.on("data", c => b.push(c));
  req.on("end", () => { res.end(Buffer.concat(b)); });
}).listen(4555, async () => {
  try {
    const form = new FormData();
    form.append("foo", "bar");
    form.append("file", new Blob(["blob-content"], {type: "image/jpeg"}), "x.jpg");
    const r = await axios.post("http://localhost:4555/", form, {maxRedirects: 0});
    console.log("FORM OK", r.data.includes("blob-content"), r.data.includes("bar"));
    const r2 = await axios.post("http://localhost:4555/", new Blob(["hello"]), {maxRedirects: 0});
    console.log("BLOB OK", r2.data);
  } catch (e) { console.error("FAIL", e); process.exitCode = 1; }
  server.close();
});
EOF
